// ---------------------------------------------------------------------------
// Behavioural equivalence: the keymap must do exactly what the five inline
// switches did.
//
// The table below was GENERATED by running the pre-refactor code (45bee38,
// "docs(cli): the help panel and ui-stream list the arrow cluster") over every
// key in every pager mode and recording the resulting state. It is a frozen
// oracle, not an aspiration: the refactor is correct exactly insofar as it
// reproduces this, and any future change to a binding has to change a line
// here on purpose.
//
// Each row is a starting state: the signature an INERT key leaves (an unbound
// control byte), plus every key that leaves something else. So a key missing
// from the map is an assertion too — it must be a no-op in that mode.
// ---------------------------------------------------------------------------

// oracleTranscript is the fixture the oracle was recorded against: eight
// two-node messages in a 50x8 pane, entered (and so following the tail).
func oracleTranscript() *transcript {
	ft := ldrender.NewFakeTerminal(50, 8)
	client := aria.NewClient()
	for i := 1; i <= 8; i++ {
		client.Apply(aria.Page{Parts: []aria.TurnPart{{Turn: aria.Turn{
			ID: uint64(i), Sealed: true,
			Nodes: []livedoc.Node{
				{Type: livedoc.NodeProse, Markdown: fmt.Sprintf("msg%02d body", i)},
				{Type: livedoc.NodeTool, Name: "bash", Output: fmt.Sprintf("out%02d", i)},
			},
		}}}})
	}
	tr := newTranscript(ft, 50, 8, ldrender.NodeText{}, client, "aria1234", time.Unix(0, 0))
	tr.enter()
	return tr
}

// oracleSignature is every piece of pager state a keystroke can touch.
func oracleSignature(tr *transcript) string {
	return fmt.Sprintf("off=%d fol=%v srch=%v q=%q mq=%q h=%v s=%v Q=%v g=%v sel=%v old=%v new=%v exp=%d",
		tr.offset, tr.follow, tr.inSearch, tr.query, tr.matchQuery,
		tr.showHelp, tr.showStatus, tr.showQueued, tr.pendG, tr.selection.active,
		tr.checkOlder, tr.checkNewer, len(tr.expanded))
}

// The starting states, by the name the oracle records them under.
var oracleStates = map[string]func(*transcript){
	"transcript":       func(tr *transcript) {},
	"transcript+sel":   func(tr *transcript) { tr.selectNode(1, false); tr.render() },
	"transcript+pendG": func(tr *transcript) { tr.key('g') },
	"help":             func(tr *transcript) { tr.key('?') },
	"status":           func(tr *transcript) { tr.key('!') },
	"queued":           func(tr *transcript) { tr.key('Q') },
	"panel+sel":        func(tr *transcript) { tr.selectNode(1, false); tr.key('!') },
	"search":           func(tr *transcript) { tr.key('/'); tr.key('m'); tr.key('s') },
	"search+sel":       func(tr *transcript) { tr.selectNode(1, false); tr.key('/'); tr.key('m') },
}

