// TestKeymap_PagerBehaviourIsUnchanged sweeps every byte and every navigation
// key through every mode and compares against the frozen oracle.
func TestKeymap_PagerBehaviourIsUnchanged(t *testing.T) {
	for _, row := range pagerOracle {
		setup, ok := oracleStates[row.state]
		if !ok {
			t.Fatalf("oracle names state %q, which the harness does not build", row.state)
		}
		t.Run(row.state, func(t *testing.T) {
			press := func(name string, press func(*transcript)) {
				tr := oracleTranscript()
				setup(tr)
				press(tr)
				want, special := row.keys[name]
				if !special {
					want = row.inert
				}
				if got := oracleSignature(tr); got != want {
					verdict := "differs from the pre-refactor dispatch"
					if !special {
						verdict = "was inert before the refactor and is not now"
					}
					t.Errorf("%s in %s mode %s:\n got %s\nwant %s", name, row.state, verdict, got, want)
				}
			}
			for b := 0; b < 128; b++ {
				b := byte(b)
				press(fmt.Sprintf("0x%02x", b), func(tr *transcript) { tr.key(b) })
			}
			for n := navUp; n <= navEnd; n++ {
				n := n
				press(navName(n), func(tr *transcript) { tr.navMotion(n) })
			}
		})
	}
}

// TestKeymap_OracleCoversEveryPagerRow: the sweep above is only as good as its
// states. Every pager-level binding must be exercised by at least one row of
// the oracle — otherwise a binding could be silently broken.
func TestKeymap_OracleCoversEveryPagerRow(t *testing.T) {
	covered := map[keyMode]bool{}
	for _, row := range pagerOracle {
		tr := oracleTranscript()
		oracleStates[row.state](tr)
		covered[tr.mode()] = true
	}
	for i := range keymap {
		bd := &keymap[i]
		if bd.pager == nil {
			continue
		}
		for m := keyMode(0); m < numKeyModes; m++ {
			if bd.modes&(1<<m) == 0 || covered[m] {
				continue
			}
			t.Errorf("%s is live in %s mode, which the equivalence oracle never starts in",
				bd.chord, modeName(m))
		}
	}
}
